contains develop
 spec/remind_who.spec.sh | 7 +++++++
 src/remind.sh           | 9 ++++++---
 2 files changed, 13 insertions(+), 3 deletions(-)
=== remind.sh on branch
     1	#!/bin/bash
     2	# remind.sh [--who NAME] DATE: one reminder per booking of the day (only NAME's with --who), from the listing.
     3	set -u
     4	who=
     5	if [ "${1:-}" = --who ]; then who=${2:-}; shift 2; fi
     6	if [ $# -ne 1 ]; then echo "usage: remind.sh [--who NAME] DATE" >&2; exit 1; fi
     7	out=$(bash "$(dirname "$0")/list.sh" "$1") || exit $?
     8	[ -z "$out" ] || printf '%s\n' "$out" | awk -v w="$who" 'w == "" || $4 == w' | while read -r d t r w; do echo "reminder to $w: $r $d $t"; done
=== spec on branch
     1	#!/bin/bash
     2	fail=0
     3	t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tsato\nkaede\t2026-01-01\t13:00\t14:00\tito\nsakura\t2026-01-01\t15:00\t16:00\tsatoh\n' > "$t"
     4	[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01)" = 'reminder to sato: aoi 2026-01-01 10:00-11:00' ] || { echo "remind --who"; fail=1; }
     5	bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
     6	[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01 | wc -l)" = 1 ] || { echo "--who matched a longer name"; fail=1; }
     7	rm -f "$t"; exit $fail
=== list.sh on branch
     1	#!/bin/bash
     2	# list.sh [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
     3	set -u
     4	BOOKINGS=${BOOKINGS:-data/bookings.tsv}
     5	[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
     6	grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" 'NF && (d == "" || $2 == d) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort
